"""Sursis conclusion and parole integrated with current CP and LEP."""
import json,sys
from pathlib import Path
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
CP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm'
LEP='https://www.planalto.gov.br/ccivil_03/leis/l7210.htm'
rows={}
def add(n,s,p,a,c,v,q,t,d):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP,CP,LEP])
add(701,'Custas e cobranças ligadas ao sursis exigem base legal atual e exame econômico.', ['Separar pena, custas e taxa histórica.'], 'Taxa penitenciária não é obrigação atual universal criada só pela redação antiga.', 'Juízo examina capacidade econômica para providência legal relativa a custas.', 'Hipossuficiência não pode ser ignorada por cobrança automática de taxa histórica.', ['Taxa antiga vale automaticamente para todos? Não.', 'Condições econômicas importam? Sim.'], 'Encargos processuais','Obrigações pecuniárias distintas da pena suspensa.')
add(702,'Sursis é individualizado: coautores podem receber decisões diferentes conforme requisitos.', ['Avaliar situação de cada condenado.', 'Motivar resultado.'], 'Concessão a um não estende automaticamente benefício aos demais.', 'Um coautor preenche requisitos; outro é reincidente doloso impeditivo.', 'Igual participação no fato não elimina diferenças pessoais legalmente relevantes.', ['Coautores precisam ter igual resultado? Não.', 'Decisão exige exame individual? Sim.'], 'Individualização','Exame dos requisitos de cada beneficiário.')
add(703,'Audiência dá ciência da sentença e condições do sursis, advertindo consequências legais.', ['Integrar LEP160–162.', 'Não confundir advertência e ameaça arbitrária.'], 'Nova infração não tem efeito único automático: distinguir revogação, prorrogação e hipótese legal.', 'Beneficiário conhece obrigações e consequências na audiência.', 'Processo por outro crime exige examinar regra atual, não imediata condenação presumida.', ['Audiência informa condições? Sim.', 'Mera acusação equivale sempre a revogação? Não.'], 'Audiência admonitória','Ciência formal das obrigações da suspensão.')
add(704,'Concessão recursal deve fixar condições e viabilizar audiência segundo competência e regime atuais.', ['Tribunal pode conceder benefício cabível.', 'Implementação exige comunicação ao juízo competente.'], 'Concessão no tribunal não dispensa ciência das condições nem fiscalização.', 'Acórdão concede sursis e determina providências de audiência.', 'Juízo de execução acompanha cumprimento sem alterar arbitrariamente benefício.', ['Concessão recursal elimina audiência? Não.', 'Condições devem ser definidas? Sim.'], 'Implementação recursal','Efetivação do benefício concedido em recurso.')
add(705,'Não comparecimento injustificado à audiência pode deixar sursis sem efeito; justo impedimento precisa ser examinado.', ['Intimação pessoal ou edital no regime pertinente.', 'Integrar LEP161 e devido processo.'], 'Ausência com internação comprovada não deve ser tratada como recusa automática.', 'Intimado falta sem justificativa; juízo apura consequência legal.', 'Impedimento grave demonstrado pode exigir nova audiência.', ['Justo impedimento importa? Sim.', 'Toda ausência significa perda automática sem exame? Não.'], 'Comparecimento admonitório','Participação exigida para ciência do benefício.')
add(706,'Aumento válido da pena em recurso pode tornar sursis incompatível com limites atuais.', ['Aplicar limites do CP77.', 'Respeitar proibição de agravar em recurso só defensivo.'], 'Não aumentar pena indevidamente só para retirar benefício; hipótese etária/saúde tem limites próprios.', 'Recurso acusatório cabível aumenta pena além da hipótese legal.', 'Recurso exclusivo da defesa não autoriza agravamento que retire sursis.', ['Recurso só defensivo permite agravamento livre? Não.', 'Aumento válido pode excluir hipótese legal? Sim.'], 'Limite do benefício','Compatibilidade do sursis com pena e requisitos.')
add(708,'Fim do prazo ou prorrogação sem causa legal de revogação exige examinar extinção da pena suspensa.', ['Integrar CP81–82 e LEP162.', 'Distinguir suspensão da pena e do processo.'], 'Não declarar extinção ignorando prorrogação legal nem manter pena indefinidamente sem fundamento.', 'Período é cumprido regularmente e juízo declara efeito extintivo.', 'Processo relevante no período exige conferir prorrogação cabível antes da conclusão.', ['Prorrogação legal deve ser conferida? Sim.', 'Sursis equivale à suspensão do processo? Não.'], 'Extinção no sursis','Conclusão do benefício no regime legal.')
add(709,'Registro do sursis e averbações integram LEP163, com sigilo e finalidades legais.', ['Registrar revogação ou extinção.', 'Pena acessória antiga não afasta automaticamente sigilo atual.'], 'Não divulgar registro irrestritamente por remissão histórica a interdição.', 'Juízo registra suspensão e posterior extinção.', 'Consulta institucional deve observar finalidade e regras de acesso.', ['Averbação deve refletir extinção? Sim.', 'Registro é publicidade irrestrita? Não.'], 'Registro sigiloso','Documentação do benefício sob limites legais.')
add(710,'Livramento exige CP83 e LEP131; frações antigas de metade ou três quartos não são regra atual universal.', ['Distinguir mais de um terço, metade ou dois terços conforme hipótese.', 'Examinar vedações especiais e requisitos subjetivos.', 'Lei13.964/2019 inclui ausência de falta grave nos últimos doze meses.'], 'Não aplicar três quartos automaticamente ao reincidente; progressão de regime é benefício distinto.', 'Não reincidente doloso com bons antecedentes exige conferir hipótese de um terço e demais requisitos.', 'Crime abrangido por regra especial pode exigir fração diversa ou vedação, sem cálculo genérico.', ['Reincidente sempre exige três quartos? Não.', 'Fração sozinha garante livramento? Não.'], 'Livramento condicional','Liberdade condicionada aos requisitos legais atuais.')
add(711,'Penas de infrações diversas devem ser somadas para livramento conforme CP84.', ['Não escolher só a condenação mais conveniente.', 'Considerar regime legal de cada título e vedações.'], 'Soma não uniformiza toda fração especial nem elimina impedimento legal.', 'Duas penas integram cálculo pertinente do benefício.', 'Crime sujeito a vedação não se torna elegível por soma a delito comum.', ['CP84 impõe soma pertinente? Sim.', 'Soma elimina toda vedação? Não.'], 'Soma para livramento','Base de cálculo integrada dos títulos.')
add(712,'Pedido ou iniciativa de livramento é processado judicialmente com regime da LEP131 e194–195.', ['Distinguir provocação e poder de conceder.', 'Garantir participação pertinente.'], 'Família ou direção pode provocar análise, mas não liberar pessoa por decisão própria.', 'Defesa apresenta documentação para exame do juiz da execução.', 'Diretor encaminha proposta, sem substituir decisão judicial.', ['Diretor concede sozinho livramento? Não.', 'Provocação exige exame judicial? Sim.'], 'Provocação executória','Iniciativa para análise jurisdicional do benefício.')
add(713,'Parecer do Conselho não vincula juiz, que decide fundamentadamente pelos requisitos atuais.', ['LEP131 prevê oitiva de MP e Conselho.', 'Distinguir parecer e decisão.'], 'Conveniente não substitui requisito legal; parecer desfavorável tampouco dispensa motivação judicial.', 'Juiz enfrenta dados do parecer e fundamenta concessão cabível.', 'Parecer favorável não permite ignorar requisito objetivo ausente.', ['Parecer vincula necessariamente juiz? Não.', 'Decisão exige requisitos legais? Sim.'], 'Parecer penitenciário','Subsídio consultivo ao exame judicial.')
add(714,'Informações penitenciárias subsidiam livramento com dados pertinentes, sem tornar relatório sentença.', ['Conduta, trabalho e situação social são elementos de análise.', 'Integrar requisitos atuais e defesa.'], 'Promessa de emprego não é requisito universal substitutivo de toda análise legal.', 'Direção informa atividades e comportamento para instruir pedido.', 'Falta de promessa particular não dispensa exame individual da aptidão e condições pertinentes.', ['Relatório decide benefício sozinho? Não.', 'Dados precisam ser relacionados aos requisitos? Sim.'], 'Relatório instrutório','Informações documentadas para exame executório.')
add(715,'Referência a medida detentiva cumulada com pena pertence ao modelo antigo e exige integração ao sistema atual.', ['Distinguir livramento de pena e desinternação de medida.', 'Não restaurar sistema duplo automático.'], 'Cessação de periculosidade da medida não pode ser aplicada indiscriminadamente como requisito de todo livramento.', 'Condenado cumpre pena e tem benefício examinado pelo CP83.', 'Internado em medida de segurança segue regime próprio de desinternação, não livramento por simples troca de nome.', ['Todo livramento exige cessação de medida cumulada? Não.', 'Desinternação e livramento são iguais? Não.'], 'Distinção de regimes','Separação de execução da pena e medida de segurança.')
add(716,'Instrução e manifestação ministerial subsidiam decisão judicial do livramento segundo LEP131.', ['Conselho pode fornecer parecer e dados.', 'Garantir decisão motivada do órgão competente.'], 'Encaminhamento não é concessão nem autoriza deferir sem verificar requisitos.', 'Parecer, relatório e pedido são examinados pelo juiz com participação legal.', 'Necessidade de diligência é avaliada sem converter consulta em atraso indefinido.', ['Encaminhar proposta equivale a conceder? Não.', 'MP é ouvido no regime legal? Sim.'], 'Instrução do benefício','Preparação dos elementos para decisão.')
add(717,'Requisito temporal ausente exige indeferimento fundamentado pela fração atual pertinente, não pelo710 antigo.', ['Usar CP83 e regras especiais.', 'Conferir cálculo e possibilidade de erro.'], 'Não indeferir por ausência de três quartos históricos se a hipótese atual exige outra fração.', 'Pedido prematuro é examinado pelo tempo legal efetivamente exigido.', 'Erro de contagem comprovado exige correção antes de concluir ausência do requisito.', ['Usar710 antigo basta para fração atual? Não.', 'Cálculo deve ser conferido? Sim.'], 'Requisito temporal','Tempo exigido pelo regime atual do benefício.')
add(718,'Condições do livramento seguem CP85 e LEP132–134, com comunicação de mudança autorizada.', ['Distinguir obrigações obrigatórias e possíveis.', 'Lei14.843/2024 prevê monitoração como condição possível.', 'Apresentação ao destino deve ser orientada.'], 'Não tratar condição possível como obrigatória universal nem confundir sursis e livramento.', 'Liberado obtém autorização para residir fora e é orientado a apresentar-se ao destino.', 'Monitoração precisa de decisão cabível, não imposição automática por qualquer caso.', ['Todas condições possíveis são obrigatórias? Não.', 'Mudança autorizada requer comunicação adequada? Sim.'], 'Condições do livramento','Obrigações individualizadas do beneficiário.')
add(719,'Custas e taxa histórica devem ser examinadas com base legal e capacidade econômica, sem barreira automática ao livramento.', ['Separar benefício e cobrança.', 'Distinguir insolvência e recusa deliberada.'], 'Não exigir pagamento universal de taxa penitenciária antiga como preço da liberdade.', 'Insolvência demonstrada é considerada no exame dos encargos cabíveis.', 'Renda disponível pode fundamentar pagamento legal, sem inventar taxa por redação histórica.', ['Insolvência pode ser ignorada? Não.', 'Taxa antiga é requisito universal atual? Não.'], 'Capacidade econômica','Condição relevante aos encargos legalmente exigíveis.')
add(720,'Multa remanescente segue CP50–51 e LEP164–170, não todo modelo antigo do688.', ['Pagamento ou parcelamento tem regime próprio.', 'Desconto protege sustento.'], 'Não converter multa em prisão nem aplicar automaticamente selo penitenciário ou quarto do salário.', 'Juízo examina cobrança legal compatível com renda.', 'Recursos indispensáveis à família não são retirados por desconto automático.', ['Não pagar permite conversão em prisão? Não.', 'Cobrança deve proteger sustento? Sim.'], 'Multa remanescente','Pena pecuniária ainda sujeita à execução legal.')
add(721,'Reforma da negativa de livramento exige implementação pelo juízo executório, conforme LEP135.', ['Fixar condições e efetivar decisão.', 'Não ignorar limites do acórdão.'], 'Acórdão favorável não pode ficar sem cumprimento por falta de encaminhamento.', 'Tribunal reforma negativa e juízo promove condições e providências.', 'Juízo não transforma cumprimento em nova negativa arbitrária do mesmo fundamento afastado.', ['Reforma exige providências de implementação? Sim.', 'Juízo pode ignorar acórdão? Não.'], 'Cumprimento recursal','Efetivação do livramento reconhecido em recurso.')
add(722,'Concessão exige carta de livramento conforme LEP136, distinta da guia de ingresso no cumprimento.', ['Cópia integral e vias pertinentes.', 'Comunicar administração e Conselho.'], 'Não confundir carta de livramento com nova ordem de prisão ou ingresso executório.', 'Decisão é documentada e encaminhada para efetivar liberdade condicionada.', 'Erro nas condições exige ajuste do documento ao título judicial.', ['Documento atual é carta de livramento? Sim.', 'Equivale a mandado de prisão? Não.'], 'Carta de livramento','Documento de efetivação do benefício.')
add(723,'Cerimônia informa sentença, condições e aceitação do liberando, integrada à LEP137.', ['Lavrar termo e encaminhar cópia.', 'Assinatura a rogo se necessário.'], 'Formalidade não autoriza condições diferentes das judicialmente fixadas ou exposição humilhante.', 'Beneficiário ouve condições e declara aceitação documentada.', 'Impossibilidade de escrever permite assinatura a rogo nos termos legais.', ['Aceitação é documentada? Sim.', 'Cerimônia permite inventar novas condições? Não.'], 'Termo de livramento','Registro da ciência e aceitação das condições.')
add(724,'Documento entregue ao liberado identifica pessoa e condições, integrado à LEP138.', ['Caderneta ou substituto legal pertinente.', 'Registrar cumprimento das condições.', 'Pena acessória antiga não é restaurada.'], 'Salvo-conduto do livramento não é imunidade geral nem HC preventivo ilimitado.', 'Liberado recebe identificação e obrigações fixadas para acompanhamento.', 'Documento não impede prisão por outro título legal válido.', ['Documento elimina qualquer ordem prisional futura? Não.', 'Deve informar condições do benefício? Sim.'], 'Documento do liberado','Identificação e orientação da liberdade condicionada.')
add(725,'Acompanhamento combina fiscalização e apoio ao beneficiário segundo LEP139.', ['Orientar obrigações e atividade laboral.', 'Comunicar fatos pertinentes ao juízo.', 'Não recuperar pena acessória histórica.'], 'Apoio não é mera vigilância punitiva nem autorização para restrições extras.', 'Patronato auxilia inserção laboral e verifica condições.', 'Dificuldade de emprego exige orientação e exame concreto, não automática declaração de crime.', ['Acompanhamento inclui auxílio? Sim.', 'Entidade pode inventar restrições? Não.'], 'Acompanhamento protetivo','Fiscalização com suporte à reintegração.')
add(726,'Revogação obrigatória segue CP86: condenação definitiva a pena privativa por crime, com distinção temporal.', ['Crime anterior e durante benefício têm efeitos próprios.', 'Não equiparar toda contravenção à regra obrigatória antiga.'], 'CP87 disciplina hipótese facultativa por crime ou contravenção com pena não privativa; identificar tipo e sanção.', 'Condenação definitiva por crime cometido no benefício exige analisar CP86.', 'Contravenção não recebe automaticamente tratamento obrigatório só pelo texto antigo.', ['Toda contravenção gera revogação obrigatória pelo726? Não.', 'Tipo de infração e sanção importam? Sim.'], 'Revogação obrigatória','Hipótese atual de retirada do benefício pelo CP86.')
add(727,'Revogação facultativa segue CP87 e LEP140; considerar obrigações e condenação definitiva pertinente.', ['Não confundir poder de revogar e dever automático.', 'Alternativas legais podem incluir advertência ou condições mais rigorosas.'], 'Penas acessórias antigas não criam fundamento autônomo atual; respeitar oitiva e decisão motivada.', 'Descumprimento é apurado e juiz avalia resposta legal.', 'Justificativa comprovada exige análise antes de tratar falta como motivo de revogação.', ['Facultativa significa sempre revogar? Não.', 'Descumprimento precisa de exame? Sim.'], 'Revogação facultativa','Decisão judicial nas hipóteses atuais discricionárias delimitadas.')
add(728,'Revogação por crime anterior pode preservar contagem do período em liberdade e permitir exame de soma para novo livramento.', ['Integrar CP86II,88 e LEP141.', 'Data do crime é decisiva, não só data da condenação.'], 'Não tratar fato anterior como ocorrido no período apenas porque julgamento veio depois.', 'Crime foi cometido antes do benefício e condenado posteriormente; aplica-se regime temporal próprio.', 'Fato cometido durante livramento pode produzir efeitos distintos sobre tempo livre.', ['Data do fato importa? Sim.', 'Toda condenação posterior significa crime posterior? Não.'], 'Crime anterior','Infração precedente ao período do benefício.')
add(729,'Revogação por fundamento distinto do crime anterior pode impedir desconto do período livre e novo livramento da mesma pena.', ['Integrar CP88 e LEP142.', 'Identificar fundamento e título atingido.'], 'Não aplicar efeitos mais graves de modo indiscriminado ao crime anterior beneficiado por exceção legal.', 'Crime cometido durante benefício leva ao exame do regime sem contagem do período livre.', 'Crime anterior exige avaliar exceção e soma pertinente.', ['Fundamento da revogação muda efeitos? Sim.', 'Todo período livre é sempre descontado? Não.'], 'Efeitos da revogação','Consequências conforme causa e momento do fato.')
add(730,'Revogação exige decisão judicial com oitiva do liberado e apuração pertinente, integrada à LEP143.', ['MP, Conselho e iniciativa judicial nas hipóteses legais.', 'Garantir prova e motivação.'], 'Relatório administrativo não revoga benefício por si nem elimina defesa.', 'Descumprimento é comunicado; liberado é ouvido e apresenta justificativa.', 'Decisão enfrenta prova antes de aplicar consequência legal.', ['Entidade revoga sozinha benefício? Não.', 'Liberado deve ser ouvido na apuração? Sim.'], 'Procedimento revocatório','Exame judicial com participação defensiva.')
add(731,'Modificação de condições exige decisão e ciência do beneficiário, conforme LEP144.', ['Distinguir alteração e revogação.', 'Preservar obrigações legalmente cabíveis.'], 'Alterar condição não permite punição retroativa por obrigação antes inexistente.', 'Horário é ajustado por decisão e comunicado formalmente.', 'Exigir comparecimento novo sem ciência não comprova automaticamente descumprimento anterior.', ['Alteração exige ciência? Sim.', 'Pode punir retroativamente condição inexistente? Não.'], 'Modificação de condições','Ajuste legal e comunicado do acompanhamento.')
add(732,'Nova infração pode fundamentar suspensão e providência cautelar cabível; revogação depende do regime e decisão legal.', ['Integrar LEP145 e CP86–90.', 'Separar notícia, apuração e condenação definitiva.', 'Não presumir culpa pela imputação.'], 'Prisão e suspensão não são revogação definitiva automática; verificar fundamento e garantias.', 'Juízo examina notícia de novo crime e medida prevista na LEP.', 'Absolvição no novo feito exige reavaliar efeitos da suspensão no regime aplicável.', ['Notícia de infração revoga definitivamente por si? Não.', 'Suspensão e revogação são distintas? Sim.'], 'Suspensão do livramento','Providência provisória sujeita à apuração e decisão próprias.')
assert len(rows)==31
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'parole units reviewed')
